# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİN YAPILARI VE DÜŞÜNCEYİ GELİŞTİRME YOLLARI (T.D.7.14-17 / T.O.7.14)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Bilgilendirici Metin Yapıları ve Tasnif</text>\n  <text x="44" y="98" font-size="11.5" fill="#334155">• Kronolojik Sıralama: Tarihî olayların</text>\n  <text x="54" y="114" font-size="11" fill="#475569">zaman sırasıyla aktarılması (Millî Mücadele).</text>\n  <text x="44" y="136" font-size="11.5" fill="#334155">• Neden-Sonuç ve Amaç-Sonuç İlişkisi:</text>\n  <text x="54" y="152" font-size="11" fill="#475569">Olayların gerekçeleri ve hedefleri.</text>\n  <text x="44" y="174" font-size="11.5" fill="#334155">• Sınıflandırma (Tasnif - T.K.7.13 / T.Y.7.10):</text>\n  <text x="54" y="190" font-size="11" fill="#475569">Unsurları ortak ölçütlere göre gruplandırma.</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Anahtar Kelimeler · Önemli Bilgiler · Derin Anlam</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Düşünceyi Geliştirme ve İkna Yolları</text>\n  <text x="378" y="98" font-size="11.5" fill="#334155">• Tanımlama: "... nedir?" sorusuna yanıt verir.</text>\n  <text x="378" y="120" font-size="11.5" fill="#334155">• Karşılaştırma: Benzerlik ve farkları kıyaslar.</text>\n  <text x="378" y="142" font-size="11.5" fill="#334155">• Örneklendirme: Soyut düşünceyi somutlar.</text>\n  <text x="378" y="164" font-size="11.5" fill="#334155">• Tanık Gösterme: Uzman sözü / alıntı paylaşır.</text>\n  <text x="378" y="186" font-size="11.5" fill="#334155">• Sayısal Verilerden Yararlanma: İstatistik sunar.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">İkna Etme Teknikleri (T.O.7.20): Kanıt ve Duygu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAPILARINA GÖRE FİİLLER: BASİT, TÜREMİŞ VE BİRLEŞİK FİİLLER</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Basit Fiiller</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yapım eki ALMAYAN, kök</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  hâlindeki fiillerdir.</text>\n  <text x="40" y="136" font-size="11" fill="#334155">• Kip ve kişi (çekim) eklerini</text>\n  <text x="40" y="152" font-size="11" fill="#334155">  alabilirler; anlam değişmez.</text>\n  <text x="40" y="176" font-size="11" font-weight="bold" fill="#1e40af">Örnekler:</text>\n  <text x="40" y="194" font-size="11" fill="#334155">• oku-du-k, gel-iyor-sun,</text>\n  <text x="40" y="210" font-size="11" fill="#334155">  koş-acak-lar, bil-meli-yiz.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Türemiş (Gövde) Fiiller</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• İsim veya fiil köküne en az bir</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  YAPIM EKİ getirilmesiyle oluşur.</text>\n  <text x="260" y="138" font-size="11" font-weight="bold" fill="#166534">İsimden Türeyenler:</text>\n  <text x="260" y="154" font-size="11" fill="#334155">• baş-la-dı, su-sa-mış, göz-le-di</text>\n  <text x="260" y="178" font-size="11" font-weight="bold" fill="#166534">Fiilden Türeyenler:</text>\n  <text x="260" y="194" font-size="11" fill="#334155">• sev-in-di, yaz-dır-dı, gör-üş-tük</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Birleşik Fiiller (3 Grup)</text>\n  <text x="480" y="98" font-size="11" font-weight="bold" fill="#92400e">a) Kurallı Birleşik Fiiller:</text>\n  <text x="480" y="114" font-size="10.5" fill="#334155">• Yeterlik (-ebil), Tezlik (-iver),</text>\n  <text x="480" y="128" font-size="10.5" fill="#334155">  Sürerlik (-edur/-ekal), Yaklaşma (-eyaz)</text>\n  <text x="480" y="150" font-size="11" font-weight="bold" fill="#92400e">b) Yardımcı Fiille Kurulanlar:</text>\n  <text x="480" y="166" font-size="10.5" fill="#334155">• et-, ol-, kıl-, eyle- (yardım etti,</text>\n  <text x="480" y="180" font-size="10.5" fill="#334155">  hissetti, sabretti, memnun oldu)</text>\n  <text x="480" y="202" font-size="11" font-weight="bold" fill="#92400e">c) Anlamca Kaynaşmış (Deyim):</text>\n  <text x="480" y="218" font-size="10.5" fill="#334155">• kulak asmak, göze girmek, başvurmak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EK-FİİL (i-mek) GÖREVLERİ VE BİRLEŞİK FİİLLERİN YAZIMI (T.Y.7.21)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Ek-Fiilin (Ek Eylemin) İki Temel Görevi</text>\n  <text x="44" y="100" font-size="11.5" font-weight="bold" fill="#991b1b">Görev A: İsim Soylu Sözcükleri Yüklem Yapar</text>\n  <text x="52" y="116" font-size="11" fill="#334155">• Bilinen geçmiş (idi): Cesur bir çocuktu.</text>\n  <text x="52" y="132" font-size="11" fill="#334155">• Duyulan geçmiş (imiş): Hava çok soğukmuş.</text>\n  <text x="52" y="148" font-size="11" fill="#334155">• Şart (ise) / Geniş zaman (-dır): Kahramandır.</text>\n  <text x="44" y="172" font-size="11.5" font-weight="bold" fill="#991b1b">Görev B: Basit Çekimli Fiili Birleşik Zamanlı Yapar</text>\n  <text x="52" y="188" font-size="11" fill="#334155">• Hikâye (idi): gel-iyor-du, çalış-acak-tı</text>\n  <text x="52" y="204" font-size="11" fill="#334155">• Rivayet (imiş) / Şart (ise): oku-r-muş, bit-er-se</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Birleşik Fiillerde Yazım Kuralları (T.Y.7.21)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Kurallı birleşik fiiller DAİMA BİTİŞİK yazılır:</text>\n  <text x="388" y="116" font-size="11" font-weight="bold" fill="#1e40af">başarabilirim, gidiverdi, bakakaldı, düşeyazdı</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• Yardımcı fiillerde ses düşmesi veya türemesi</text>\n  <text x="388" y="156" font-size="11.5" fill="#334155">VARSA bitişik, YOKSA ayrı yazılır:</text>\n  <text x="388" y="174" font-size="11" font-weight="bold" fill="#15803d">Bitişik: sabretti (sabır), hissetti (his), kayboldu</text>\n  <text x="388" y="192" font-size="11" font-weight="bold" fill="#b91c1c">Ayrı: yardım etti, fark etti, mutlu oldu, arz etti</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Deyimleşmiş fiiller ayrı yazılır: kulak asmak, göz atmak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
